export function createSceneLegacy() {
// ── portraits.js: normalizeLocationPath ──
/** Normalize a location path to `Segment :: Segment` form. */
function normalizeLocationPath(path) {
    if (!path) return '';
    return path.split('::').map(p => p.trim()).filter(Boolean).join(' :: ');
}

// ── location-resolver.js ──
/**
 * Tokenize freeform location text for loose matching against lore paths.
 * @param {string} raw
 * @returns {string[]}
 */
function tokenizeLocationText(raw) {
    if (!raw) return [];
    let text = String(raw).trim();
    if (!text) return [];

    text = text
        .replace(/\s*::\s*/g, ' ')
        .replace(/[,/]/g, ' ')
        .replace(/\s*[—–]\s*/g, ' ')
        .replace(/\s+/g, ' ')
        .trim();

    return text
        .split(' ')
        .map(t => t.toLowerCase())
        .filter(Boolean);
}

/**
 * @param {string} part
 * @returns {string[]}
 */
function partToTokens(part) {
    return String(part || '')
        .toLowerCase()
        .trim()
        .split(/\s+/)
        .filter(Boolean);
}

/**
 * @param {string[]} parts
 * @returns {string[]}
 */
function pathPartsToTokens(parts) {
    const seq = [];
    for (const part of parts) {
        seq.push(...partToTokens(part));
    }
    return seq;
}

/**
 * @param {string[]} inputTokens
 * @param {string[]} pathTokens
 * @returns {boolean}
 */
function tokensSuffixMatch(inputTokens, pathTokens) {
    if (!pathTokens.length || pathTokens.length > inputTokens.length) return false;
    const start = inputTokens.length - pathTokens.length;
    for (let i = 0; i < pathTokens.length; i++) {
        if (inputTokens[start + i] !== pathTokens[i]) return false;
    }
    return true;
}

/**
 * Loosely resolve freeform location text to a canonical lore path.
 * Deepest suffix match wins (e.g. "Monastery Courtyard" → "Monastery :: Courtyard").
 * @param {string} rawText
 * @param {string[]} allPaths Canonical paths using ` :: ` separators
 * @param {{ activeLocPaths?: string[], preferLeafOnly?: boolean }} [opts]
 * @returns {string|null}
 */
function resolveCurrentLocationPath(rawText, allPaths, opts = {}) {
    if (!rawText || !Array.isArray(allPaths) || allPaths.length === 0) return null;

    const inputTokens = tokenizeLocationText(rawText);
    if (!inputTokens.length) return null;

    const normalizedPaths = allPaths
        .map(p => normalizeLocationPath(p))
        .filter(Boolean);

    const activeSet = new Set((opts.activeLocPaths || []).map(p => normalizeLocationPath(p)));

    let bestPath = null;
    let bestScore = -1;

    for (const path of normalizedPaths) {
        const parts = path.split(' :: ');
        const pathTokens = pathPartsToTokens(parts);
        if (!pathTokens.length) continue;

        if (!tokensSuffixMatch(inputTokens, pathTokens)) continue;

        let score = parts.length * 1000 + pathTokens.length;
        if (activeSet.has(path)) score += 50;
        if (normalizeLocationPath(rawText) === path) score += 500;

        if (score > bestScore) {
            bestScore = score;
            bestPath = path;
        }
    }

    if (bestPath) return bestPath;

    // Leaf-only fallback: "Courtyard" → "... :: Courtyard"
    const leafToken = inputTokens[inputTokens.length - 1];
    const leafCandidates = normalizedPaths.filter((path) => {
        const parts = path.split(' :: ');
        const leaf = parts[parts.length - 1];
        return partToTokens(leaf).join(' ') === leafToken
            || (partToTokens(leaf).length === 1 && partToTokens(leaf)[0] === leafToken);
    });

    if (leafCandidates.length === 0) return null;

    const activeLeaf = leafCandidates.find(p => activeSet.has(p));
    if (activeLeaf) return activeLeaf;

    if (inputTokens.length > 1) {
        const parentTokens = inputTokens.slice(0, -1);
        const parentHint = parentTokens.join(' ');
        const hinted = resolveCurrentLocationPath(
            `${parentHint} ${leafCandidates[0].split(' :: ').pop()}`,
            leafCandidates,
            { activeLocPaths: opts.activeLocPaths },
        );
        if (hinted) return hinted;
    }

    return leafCandidates.sort((a, b) => b.split(' :: ').length - a.split(' :: ').length)[0];
}

/**
 * @param {string} path
 * @returns {string}
 */
function formatLocationBreadcrumb(path) {
    if (!path) return '';
    return normalizeLocationPath(path)
        .split(' :: ')
        .map(seg => seg.trim())
        .filter(Boolean)
        .join(' › ');
}

// ── src/state/present-now.js ──
/**
 * Latest narrator/assistant chat message, walking newest-first.
 * User and system messages are skipped so Present Now stays on the last
 * narrator output instead of emptying when the player sends a turn.
 *
 * @param {Array<{ is_user?: boolean, is_system?: boolean, is_hidden?: boolean, extra?: object }>} chat
 * @param {{ includeHidden?: boolean }} [opts]
 * @returns {object|null}
 */
function findMostRecentNarratorMessage(chat, { includeHidden = false } = {}) {
    if (!Array.isArray(chat) || chat.length === 0) return null;
    for (let i = chat.length - 1; i >= 0; i--) {
        const msg = chat[i];
        if (!msg || msg.is_user || msg.is_system) continue;
        if (!includeHidden && msg.is_hidden) continue;
        const extra = msg.extra || {};
        if (extra.summary || extra.is_summary || extra.summary_data) continue;
        return msg;
    }
    return null;
}

const CHOICES_BLOCK_RE = /<choices\b[^>]*>[\s\S]*?<\/choices\s*>/gi;
const ESCAPED_CHOICES_BLOCK_RE = /&lt;\s*choices\b[^&]*&gt;[\s\S]*?&lt;\s*\/\s*choices\s*&gt;/gi;
const CYOA_CHOICES_DIV_RE = /<div\b[^>]*\brt-cyoa-choices\b[^>]*>[\s\S]*?<\/div\s*>/gi;
const BUTTON_BLOCK_RE = /<button\b[^>]*>[\s\S]*?<\/button\s*>/gi;
const ESCAPED_BUTTON_BLOCK_RE = /&lt;\s*button\b[^&]*&gt;[\s\S]*?&lt;\s*\/\s*button\s*&gt;/gi;

/**
 * Remove CYOA choice markup (and its inner text) so Present Now only sees
 * narrative prose. Hypothetical names in choice/button blocks are not scene presence.
 *
 * @param {string} text
 * @returns {string}
 */
function stripCyoaChoiceBlocks(text) {
    let raw = String(text || '');
    if (!raw) return '';
    raw = raw.replace(CHOICES_BLOCK_RE, '');
    raw = raw.replace(ESCAPED_CHOICES_BLOCK_RE, '');
    raw = raw.replace(CYOA_CHOICES_DIV_RE, '');
    raw = raw.replace(BUTTON_BLOCK_RE, '');
    raw = raw.replace(ESCAPED_BUTTON_BLOCK_RE, '');
    return raw.replace(/\n{3,}/g, '\n\n').trim();
}

// ── router.js: isNpcBookName ──
/** @param {string} bookName */
function isNpcBookName(bookName) {
    const lower = (bookName || '').toLowerCase();
    return lower.endsWith('_npcs') || lower.endsWith('_npc') || lower === 'npcs' || lower === 'npc';
}

// ── router.js: narrativeMentionsNpcName ──
/**
 * True if narrative text mentions the NPC's full name, or any first/last name token.
 * Case-sensitive word-boundary match; ignores parenthetical suffixes and very short tokens.
 * @param {string} narrativeText
 * @param {string} npcLabel
 * @param {{ requireFullName?: boolean }} [opts] When true, only a full-name match counts (no first/last token).
 * @returns {boolean}
 */
function narrativeMentionsNpcName(narrativeText, npcLabel, opts = {}) {
    const text = String(narrativeText || '');
    const cleaned = String(npcLabel || '')
        .replace(/\s*\(.*?\)/g, '')
        .replace(/[^\p{L}\p{N}\s'-]/gu, ' ')
        .replace(/\s+/g, ' ')
        .trim();
    if (!cleaned || text.length === 0) return false;

    const escapeRe = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const wordBoundaryRe = (phrase) => new RegExp(
        `(?:^|[^\\p{L}\\p{N}])${phrase}(?:[^\\p{L}\\p{N}]|$)`,
        'u',
    );

    if (cleaned.length >= 2) {
        const fullPattern = escapeRe(cleaned).replace(/\s+/g, '\\s+');
        if (wordBoundaryRe(fullPattern).test(text)) return true;
    }

    if (opts.requireFullName) return false;

    const tokens = cleaned.split(/\s+/).filter(t => t.length >= 2);
    for (const token of tokens) {
        if (wordBoundaryRe(escapeRe(token)).test(text)) return true;
    }
    return false;
}

    return {
        normalizeLocationPath,
        tokenizeLocationText,
        resolveCurrentLocationPath,
        formatLocationBreadcrumb,
        findMostRecentNarratorMessage,
        stripCyoaChoiceBlocks,
        isNpcBookName,
        narrativeMentionsNpcName,
    };
}
